"""Immutable EXE build metadata, generated by the PyInstaller spec."""

import datetime
import json
import logging
from pathlib import Path
import sys


BUILD_TIMEZONE = datetime.timezone(datetime.timedelta(hours=8))
MANIFEST_NAME = "build_info.json"


def write_build_manifest(directory, *, built_at=None):
    """Stamp every packaging run; never edit a version constant in the source."""
    built_at = built_at or datetime.datetime.now(BUILD_TIMEZONE)
    if built_at.tzinfo is None:
        raise ValueError("Build time must include its timezone")
    built_at = built_at.astimezone(BUILD_TIMEZONE)
    payload = {"build_date": built_at.date().isoformat(),
               "built_at": built_at.isoformat(timespec="microseconds")}
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    manifest = directory / MANIFEST_NAME
    manifest.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    return manifest


def get_build_info():
    if not getattr(sys, "frozen", False):
        return {"version": "Python source (not packaged)", "build_date": None, "built_at": None, "runtime": "python"}
    unknown = {"version": "unknown (build date unavailable)", "build_date": None, "built_at": None, "runtime": "exe"}
    try:
        # Filesystem creation/modification dates can change when an EXE is copied.
        root = getattr(sys, "_MEIPASS", None)
        if not root:
            return unknown
        payload = json.loads((Path(root) / MANIFEST_NAME).read_text(encoding="utf-8"))
        date = datetime.date.fromisoformat(payload["build_date"])
        built_at = datetime.datetime.fromisoformat(payload["built_at"])
        if built_at.tzinfo is None or built_at.astimezone(BUILD_TIMEZONE).date() != date:
            raise ValueError("Inconsistent EXE build metadata")
        return {"version": date.strftime("%m.%d.%Y"), "build_date": date.isoformat(),
                "built_at": built_at.isoformat(), "runtime": "exe"}
    except (OSError, ValueError, TypeError, KeyError):
        logging.warning("Packaged EXE build metadata is unavailable or invalid.")
        return unknown


def build_version_footer(build_info=None):
    info = build_info if build_info is not None else get_build_info()
    # Timestamp distinguishes EXEs built on the same day; the requested label is last.
    lines = []
    if info.get("built_at"):
        lines.append("EXE built: " + info["built_at"])
    lines.append("SADM Autorouter version " + info["version"])
    return "\n".join(lines)
